do $$begin
 if (select count(*) from literacy_mock_incoming) <> 10985
  or (select count(distinct item->>'id') from literacy_mock_incoming) <> 10985 then
  raise exception 'Incomplete V13 scored bank or V12 prerequisite';
 end if;
 if exists(select 1 from literacy_mock_incoming incoming join public.literacy_mock_items old
  on old.id=incoming.item->>'id' and old.content_version='literacy-mock-v13'
  where old.item is distinct from incoming.item) then raise exception 'Cannot rewrite immutable V13 publication'; end if;
 if exists(select 1 from public.literacy_mock_publications where content_version='literacy-mock-v13' and item_count<>10985) then
  raise exception 'Published mock catalogue count is immutable';
 end if;
end; $$;
insert into public.literacy_mock_items(id,content_version,item)
select item->>'id','literacy-mock-v13',item from literacy_mock_incoming on conflict(id,content_version) do nothing;
insert into public.literacy_mock_publications(content_version,item_count)
values('literacy-mock-v13',10985) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v13')<>10985
  then raise exception 'Incomplete V13 publication'; end if;
end; $$;
notify pgrst,'reload schema';
commit;
